//! Rails schema: the tables, columns, keys, indexes and foreign keys a Rails
//! application's `db/schema.rb` declares, read without running Ruby.
//!
//! `db/schema.rb` is generated by Active Record's schema dumper, so it holds a
//! small, regular part of Ruby: `create_table` blocks of column, index and
//! constraint calls, `add_foreign_key`, `create_enum` and `enable_extension`.
//! Reading it statically needs no Ruby, Bundler, gems or database, so any
//! revision can be extracted, however old its dependencies.

mod build;
mod read;

pub use build::shown_type;

use anyhow::{Result, bail, ensure};
use projections_extractor_ruby_support::{inflect::Inflections, parse};
use projections_extractor_sdk::{Context, Descriptor, Trust, database_extraction, pre_exported_schema, strings};
use serde_json::{Value, json};

pub const ID: &str = "rails-schema";

pub fn descriptor() -> Descriptor {
    Descriptor {
        id: ID,
        title: "Rails schema",
        description: "Rails db/schema.rb: tables, columns, keys, indexes, foreign keys and enums",
        schema: "database/v0",
        renderer: "database",
        trust: Trust::None,
        access: projections_extractor_sdk::Access::Files,
        determinism: projections_extractor_sdk::Determinism::Pure,
        inputs: json!({
            "schema": "Schema file (db/schema.rb or db/<database>_schema.rb); otherwise discovers the application's schema files",
            "schemas": "Multiple schema files",
            "inflections": "Inflections initializer; default config/initializers/inflections.rb beside db/",
            "snapshot": "Pre-exported effective schema",
        }),
        template_inputs: None,
        detects: &["db/schema.rb", "**/db/schema.rb", "db/*_schema.rb", "**/db/*_schema.rb"],
    }
}

pub fn requires_trust(_inputs: &Value) -> bool {
    false
}

const LIMITATIONS: [&str; 5] = [
    "The schema db/schema.rb declares, not a live database or the migrations that produced it; no Ruby, gem or database is involved.",
    "db/structure.sql (config.active_record.schema_format = :sql) isn't read.",
    "Column types are Rails types with their limit, precision and scale, not the adapter's SQL types.",
    "Statements other than Active Record's schema declarations (execute, plugin statements, conditionals) are listed in metadata.skipped, not interpreted.",
    "Default foreign-key columns follow ActiveSupport's inflections plus the irregular, uncountable, plural and singular rules the inflections initializer declares.",
];

/// Directories whose schema files describe other applications: tests' dummy apps, fixtures, vendored code.
const IGNORED: [&str; 8] = ["test", "tests", "spec", "fixtures", "examples", "vendor", "node_modules", "tmp"];

/// The application root of a schema file (`web/` for `web/db/schema.rb`) and its database name.
fn schema_file(path: &str) -> Option<(&str, &str)> {
    let (root, name) = match path.rsplit_once("db/") {
        Some((root, name)) if root.is_empty() || root.ends_with('/') => (root, name),
        _ => return None,
    };
    let database = name.strip_suffix("schema.rb")?;
    match database {
        "" => Some((root, "")),
        _ => database
            .strip_suffix('_')
            .filter(|d| !d.contains('/') && !d.is_empty())
            .map(|d| (root, d)),
    }
}

fn ignored(path: &str) -> bool {
    path.split('/').rev().skip(1).any(|segment| IGNORED.contains(&segment))
}

/// The schema files to read: those selected, or the one application's own.
fn schema_files(cx: &Context, files: &[String], definition: &Value) -> Result<Vec<String>> {
    let selected = definition["inputs"].get("schemas").or_else(|| definition["inputs"].get("schema"));
    let selected = match selected {
        Some(Value::String(s)) => vec![s.clone()],
        Some(v) => strings(v, "Rails schemas")?,
        None => {
            let found: Vec<&String> = files.iter().filter(|f| !ignored(f) && schema_file(f).is_some()).collect();
            let mut roots: Vec<&str> = found.iter().filter_map(|f| schema_file(f).map(|(root, _)| root)).collect();
            roots.sort();
            roots.dedup();
            if roots.len() > 1 {
                let roots: Vec<String> = roots.iter().map(|r| format!("{r}db/schema.rb")).collect();
                bail!(
                    "The repository has more than one Rails application ({}); select one with inputs.schema",
                    roots.join(", ")
                );
            }
            return Ok(found.into_iter().cloned().collect());
        }
    };
    ensure!(!selected.is_empty(), "inputs.schemas must name at least one schema file");
    let mut present = Vec::new();
    for file in selected {
        // A revision before the schema existed has no tables.
        if cx.input_exists(&file)? {
            present.push(file);
        }
    }
    Ok(present)
}

/// The inflections a schema file's application declares, if its initializer exists.
fn inflections(cx: &Context, files: &[String], schemas: &[String], definition: &Value) -> Result<(Inflections, Option<String>)> {
    let mut inflections = Inflections::default();
    let path = match definition["inputs"].get("inflections") {
        Some(path) => Some(projections_extractor_sdk::text(path, "inputs.inflections")?.to_owned()),
        None => schemas
            .first()
            .and_then(|s| schema_file(s))
            .map(|(root, _)| format!("{root}config/initializers/inflections.rb"))
            .filter(|path| files.contains(path)),
    };
    let Some(path) = path.filter(|p| cx.input_exists(p).unwrap_or(false)) else {
        return Ok((inflections, None));
    };
    inflections.read(&parse(&cx.read_source(&path)?, &path)?);
    Ok((inflections, Some(path)))
}

/// Reads schema files, given as repository-relative paths and contents, with the application's inflections.
pub fn extract(sources: &[(String, String)], inflections: &Inflections) -> Result<Value> {
    let mut schemas = Vec::new();
    for (path, source) in sources {
        schemas.push(read::read(&parse(source, path)?, path, inflections)?);
    }
    let read: Vec<build::Source> = sources
        .iter()
        .zip(&schemas)
        .map(|((path, _), schema)| build::Source {
            path,
            database: schema_file(path).map_or("", |(_, database)| database),
            schema,
        })
        .collect();
    let (entities, relationships) = build::extraction(&read)?;
    let skipped: Vec<Value> = read
        .iter()
        .flat_map(|source| {
            source
                .schema
                .skipped
                .iter()
                .map(|(line, text)| json!({"source":source.path,"line":line,"text":text}))
        })
        .collect();
    // Extensions are metadata: the database renderer draws tables, enums and their keys.
    let extensions: Vec<Value> = read
        .iter()
        .flat_map(|source| source.schema.extensions.iter().map(|e| json!({"source":source.path,"name":e.name})))
        .collect();
    let versions: Vec<Value> = read
        .iter()
        .map(|source| json!({"source":source.path,"format":source.schema.format,"version":source.schema.version}))
        .collect();
    Ok(json!({
        "protocolVersion": 0,
        "schema": "database/v0",
        "entities": entities,
        "relationships": relationships,
        "metadata": {
            "framework": "rails",
            "authority": "Rails db/schema.rb, read by Projections",
            "sources": sources.iter().map(|(path, _)| path).collect::<Vec<_>>(),
            "schemaVersions": versions,
            "extensions": extensions,
            "skipped": skipped,
            "limitations": LIMITATIONS,
        },
    }))
}

pub fn collect(cx: &Context) -> Result<Value> {
    let (files, d) = (cx.files()?, cx.definition());
    if d["inputs"].get("snapshot").is_some() {
        return pre_exported_schema(cx, d);
    }
    let paths = schema_files(cx, files, d)?;
    let (inflections, inflections_path) = inflections(cx, files, &paths, d)?;
    for rule in &inflections.unread {
        cx.diagnose(&format!("Inflection rule not read: {rule}"));
    }
    let sources = paths
        .into_iter()
        .map(|file| Ok((file.clone(), cx.read_source(&file)?)))
        .collect::<Result<Vec<_>>>()?;
    let mut extraction = extract(&sources, &inflections)?;
    for skipped in extraction["metadata"]["skipped"].as_array().into_iter().flatten() {
        cx.diagnose(&format!(
            "{}:{}: not a schema declaration Projections reads: {}",
            skipped["source"].as_str().unwrap_or_default(),
            skipped["line"],
            skipped["text"].as_str().unwrap_or_default()
        ));
    }
    if let Some(path) = inflections_path {
        extraction["metadata"]["inflections"] = json!(path);
    }
    database_extraction(extraction)
}
